using System;
using System.Windows;
using System.Windows.Controls;
partial class Shelf {
 bool searchExpanded=false;FrameworkElement brandWords,topLibraryHeading;
 void UpdateTopLayout(){if(brandWords!=null)brandWords.Visibility=ActualWidth<1150||(searchExpanded&&ActualWidth<1420)?Visibility.Collapsed:Visibility.Visible;if(topLibraryHeading!=null)topLibraryHeading.Visibility=searchExpanded&&ActualWidth<1050?Visibility.Collapsed:Visibility.Visible;}
 void ExpandSearch(bool expanded,bool focus=true){searchExpanded=expanded;double size=toolNav.Count>0?toolNav[0].Height:42;searchBox.Height=size;searchBox.Width=expanded?Math.Max(180,Math.Min(260,ActualWidth*.23)):size;searchBox.Padding=new Thickness(0);search.Visibility=expanded?Visibility.Visible:Visibility.Collapsed;searchHint.Visibility=expanded&&search.Text.Length==0?Visibility.Visible:Visibility.Collapsed;searchBox.ToolTip=expanded?null:"搜索游戏 · Ctrl+F";UpdateTopLayout();if(expanded&&focus)search.Focus();}
 void InstallCompactSearch(){var input=searchBox.Child as Grid;if(input!=null)input.Width=double.NaN;search.Padding=new Thickness(39,0,10,0);search.VerticalContentAlignment=VerticalAlignment.Center;searchBox.PreviewMouseLeftButtonDown+=(o,e)=>{if(!searchExpanded){ExpandSearch(true);e.Handled=true;}};search.LostKeyboardFocus+=(o,e)=>Dispatcher.BeginInvoke(new Action(()=>{if(search.Text.Length==0&&!search.IsKeyboardFocused&&modal!="search")ExpandSearch(false,false);}));ExpandSearch(false,false);}
 void CompactHeader(){var header=main.Children[0] as Grid;var intro=main.Children[1] as Grid;var nav=main.Children[2] as Grid;if(header==null||intro==null||nav==null)return;
  var brand=header.Children[0] as StackPanel;brandWords=brand!=null&&brand.Children.Count>1?brand.Children[1] as FrameworkElement:null;var tools=toolNav[0].Parent as StackPanel;var right=nav.Children[1] as StackPanel;
  intro.Children.Remove(searchBox);searchBox.Margin=new Thickness(8,0,8,0);var oldHeading=section.Parent as StackPanel;if(oldHeading!=null){oldHeading.Children.Remove(section);oldHeading.Children.Remove(countText);}var heading=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(12,0,12,0)};section.FontSize=19;countText.FontSize=11;countText.Margin=new Thickness(8,2,0,0);heading.Children.Add(section);heading.Children.Add(countText);topLibraryHeading=heading;
  nav.Children.Remove(filterButtons);nav.Children.Remove(right);var categories=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};categories.Children.Add(filterButtons);if(right!=null){right.Margin=new Thickness(8,0,0,0);categories.Children.Add(right);}
  header.ColumnDefinitions.Clear();for(int i=0;i<5;i++)header.ColumnDefinitions.Add(new ColumnDefinition{Width=i==2?new GridLength(1,GridUnitType.Star):GridLength.Auto});Grid.SetColumn(heading,1);Grid.SetColumn(categories,2);Grid.SetColumn(searchBox,3);if(tools!=null)Grid.SetColumn(tools,4);header.Children.Add(heading);header.Children.Add(categories);header.Children.Add(searchBox);header.Margin=new Thickness(0,0,0,10);
  intro.Visibility=Visibility.Collapsed;nav.Visibility=Visibility.Collapsed;main.RowDefinitions[1].Height=new GridLength(0);main.RowDefinitions[2].Height=new GridLength(0);if(focusCaption!=null)focusCaption.Visibility=Visibility.Collapsed;InstallCompactSearch();UpdateTopLayout();
 }
}
